module ReedSolomon_Top ( CLK, RESET, enc_enable, enc_startPls, enc_dataIn, 
        enc_dataOut, dec_enable, dec_sync, dec_erasureIn, dec_dataIn, 
        dec_outStartPls, dec_outDone, dec_outData, dec_errorNum, 
        dec_erasureNum, dec_fail, dec_outEnable, dec_delayedData );
  input [7:0] enc_dataIn;
  output [7:0] enc_dataOut;
  input [7:0] dec_dataIn;
  output [7:0] dec_outData;
  output [7:0] dec_errorNum;
  output [7:0] dec_erasureNum;
  output [7:0] dec_delayedData;
  input CLK, RESET, enc_enable, enc_startPls, dec_enable, dec_sync,
         dec_erasureIn;
  output dec_outStartPls, dec_outDone, dec_fail, dec_outEnable;
  wire   n1;

  RsEncodeTop u_encoder ( .CLK(CLK), .RESET(n1), .enable(enc_enable), 
        .startPls(enc_startPls), .dataIn(enc_dataIn), .dataOut(enc_dataOut) );
  RsDecodeTop u_decoder ( .CLK(CLK), .RESET(RESET), .enable(dec_enable), 
        .startPls(dec_sync), .erasureIn(dec_erasureIn), .dataIn(dec_dataIn), 
        .outEnable(dec_outEnable), .outStartPls(dec_outStartPls), .outDone(
        dec_outDone), .errorNum(dec_errorNum), .erasureNum(dec_erasureNum), 
        .fail(dec_fail), .delayedData(dec_delayedData), .outData(dec_outData)
         );
  CKBD0BWP12T30P140 U1 ( .I(RESET), .Z(n1) );
endmodule

